const results=await Promise.allSettled([
 tools.exec_command({cmd:"sed -n '1,260p' qutebrowser/misc/guiprocess.py","workdir":"/app","max_output_tokens":4000}),
 tools.exec_command({cmd:"find tests -iname '*guiprocess*' -o -iname '*process*' | head -80","workdir":"/app","max_output_tokens":1000}),
 tools.exec_command({cmd:"git status --short","workdir":"/app","max_output_tokens":500})
]);for(const x of results)text(x.status==="fulfilled"?x.value.output:String(x.reason));

const results=await Promise.allSettled([
 tools.exec_command({cmd:"sed -n '1,360p' tests/unit/misc/test_guiprocess.py","workdir":"/app","max_output_tokens":6000}),
 tools.exec_command({cmd:"find .. -name AGENTS.md -print","workdir":"/app","max_output_tokens":400}),
 tools.exec_command({cmd:"grep -R -n \"failed to start:\\|crashed:\\|Error while spawning\" tests/unit/misc tests/unit | head -80","workdir":"/app","max_output_tokens":1500})
]);for(const x of results)text(x.status==="fulfilled"?x.value.output:String(x.reason));

const results=await Promise.allSettled([
 tools.exec_command({cmd:"pytest -q tests/unit/misc/test_guiprocess.py -k 'not test_exit_crash' --tb=short --reruns 0","workdir":"/app","yield_time_ms":30000,"max_output_tokens":1000}),
 tools.exec_command({cmd:"git diff --check && git diff --stat && git status --short","workdir":"/app","yield_time_ms":10000,"max_output_tokens":500})
]);for(const x of results)text(x.status==="fulfilled"?x.value:String(x.reason));
